    { q: R('Что сделать с грота-шкотом в начале взятия рифа?', 'What do you do with the mainsheet at the start of reefing?'), o: [R('Выбрать до упора', 'Sheet hard in'), R('Потравить, чтобы парус заполаскивал', 'Ease it so the sail luffs'), R('Ничего', 'Nothing')], a: 1, e: R('Парус без нагрузки легче опустить.', 'An unloaded sail is easier to lower.') },
    { q: R('Что поддерживает гик, пока фал потравлен?', 'What holds the boom up while the halyard is eased?'), o: [R('Топенант', 'Topping lift'), R('Оттяжка гика', 'Kicker'), R('Ахтерштаг', 'Backstay')], a: 0, e: R('Топенант не даёт гику упасть на кокпит.', 'The topping lift stops the boom dropping into the cockpit.') },
    { q: R('Как подвязывают риф-сезни?', 'How are reef points tied?'), o: [R('Вокруг гика', 'Round the boom'), R('Только вокруг паруса', 'Round the sail only'), R('Их не подвязывают', 'They are not tied')], a: 1, e: R('Сезни вокруг гика рвут парус при нагрузке.', 'Ties round the boom tear the sail under load.') },
    { q: R('Какой признак говорит, что пора рифиться?', 'Which sign says it is time to reef?'), o: [R('Постоянный крен больше 20° и тяжёлый руль', 'Steady heel over 20° and a heavy helm'), R('Колдунчики летят ровно', 'Telltales stream evenly'), R('Скорость выше 5 узлов', 'Speed over 5 knots')], a: 0, e: R('Крен и тенденция к приведению — главные сигналы.', 'Heel and weather helm are the main signals.') },
    { type: 'order', q: R('Расставьте шаги взятия рифа на гроте.', 'Put the steps of reefing the main in order.'), steps: [R('Лечь в бейдевинд, потравить грота-шкот', 'Head close-hauled, ease the mainsheet'), R('Выбрать топенант, ослабить оттяжку гика', 'Take up the topping lift, ease the kicker'), R('Потравить фал, закрепить риф-кренгельс у гика', 'Lower the halyard, secure the luff cringle'), R('Обтянуть фал', 'Re-tension the halyard'), R('Обтянуть риф-шкентель задней шкаторины', 'Haul in the leech reef line'), R('Выбрать шкот и лечь на курс', 'Sheet in and resume course')], e: R('Сначала снимаем нагрузку, затем опускаем, крепим и снова натягиваем.', 'First unload, then lower, secure and re-tension.') }
